window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-30df05c99bb4cd43"]={"versions": [{"id": "FIG-30df05c99bb4cd43", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Software Component Template) zur Klassifikation von AUTOSAR-Software-Komponenten und deren Prototypisierung im Kontext der Runtime Environment (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die abstrakte Basisklasse <code>SwComponentType</code> (spezialisiert aus <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>). Direkt von <code>SwComponentType</code> erben:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code>: Kompositionskomponente, aggregiert über die gerichtete Komposition <code>+component 0..*</code> (stereotypisiert mit <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>SwComponentPrototype</code>.\n</li><li><code>ParameterSwComponentType</code>: Komponente zur Bereitstellung von Kalibrier- und Konfigurationsparametern.\n</li><li><code>AtomicSwComponentType</code> (abstrakt): atomare Basiskomponente, von der die konkreten Komponententypen ableiten:\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code>\n</li><li><code>SensorActuatorSwComponentType</code>\n</li><li><code>EcuAbstractionSwComponentType</code>\n</li><li><code>ComplexDeviceDriverSwComponentType</code>\n</li><li><code>NvBlockSwComponentType</code>\n</li><li><code>ServiceSwComponentType</code>\n</li><li><code>ServiceProxySwComponentType</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Klasse <code>SwComponentPrototype</code> (spezialisiert aus <code>AtpPrototype</code>) referenziert über die gerichtete Assoziation <code>«isOfType»</code> mit der Kardinalität <code>*</code> zu <code>1</code> (<code>+type {redefines atpType}</code>) den zugrundeliegenden <code>SwComponentType</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Laufzeitsequenzen dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Vererbungshierarchie und Typisierung für das AUTOSAR-Komponentenmodell:</p>\n<ul class=\"fig-list\"><li>Die abstrakten Klassen <code>SwComponentType</code> und <code>AtomicSwComponentType</code> dürfen nicht direkt instanziiert werden; instanziierbar sind ausschließlich die abgeleiteten konkreten Typen bzw. Kompositionen.\n</li><li>Ein <code>SwComponentPrototype</code> verlangt genau eine Typbindung (<code>+type 1</code>), während ein <code>SwComponentType</code> von beliebig vielen Prototypen instanziiert werden kann.\n</li><li>Kompositionen kapseln Subkomponenten über <code>0..*</code> Prototypen, wobei Variationspunkte und Splitbarkeit (<code>«atpVariation,atpSplitable»</code>) auf der Kompositionsbeziehung unterstützt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2d2f806c5b31cc99", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Software Component Template) zur Klassifikation von AUTOSAR-Software-Komponenten und deren Prototypisierung im Kontext der Runtime Environment (RTE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die abstrakte Basisklasse <code>SwComponentType</code> (spezialisiert aus <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>). Direkt von <code>SwComponentType</code> erben:</p>\n<ul class=\"fig-list\"><li><code>CompositionSwComponentType</code>: Kompositionskomponente, aggregiert über die gerichtete Komposition <code>+component 0..*</code> (stereotypisiert mit <code>«atpVariation,atpSplitable»</code>) Instanzen von <code>SwComponentPrototype</code>.\n</li><li><code>ParameterSwComponentType</code>: Komponente zur Bereitstellung von Kalibrier- und Konfigurationsparametern.\n</li><li><code>AtomicSwComponentType</code> (abstrakt): atomare Basiskomponente, von der die konkreten Komponententypen ableiten:\n<ul class=\"fig-list\"><li><code>ApplicationSwComponentType</code>\n</li><li><code>SensorActuatorSwComponentType</code>\n</li><li><code>EcuAbstractionSwComponentType</code>\n</li><li><code>ComplexDeviceDriverSwComponentType</code>\n</li><li><code>NvBlockSwComponentType</code>\n</li><li><code>ServiceSwComponentType</code>\n</li><li><code>ServiceProxySwComponentType</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Klasse <code>SwComponentPrototype</code> (spezialisiert aus <code>AtpPrototype</code>) referenziert über die gerichtete Assoziation <code>«isOfType»</code> (<code>+type 1 {redefines atpType}</code>) den zugrundeliegenden <code>SwComponentType</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Laufzeitsequenzen dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Vererbungshierarchie und Typisierung für das AUTOSAR-Komponentenmodell:</p>\n<ul class=\"fig-list\"><li>Die abstrakten Klassen <code>SwComponentType</code> und <code>AtomicSwComponentType</code> dürfen nicht direkt instanziiert werden; instanziierbar sind ausschließlich die abgeleiteten konkreten Typen bzw. Kompositionen.\n</li><li>Ein <code>SwComponentPrototype</code> verlangt genau eine Typbindung (<code>+type 1</code>), während ein <code>SwComponentType</code> von beliebig vielen Prototypen instanziiert werden kann.\n</li><li>Kompositionen kapseln Subkomponenten über <code>0..*</code> Prototypen, wobei Variationspunkte und Splitbarkeit (<code>«atpVariation,atpSplitable»</code>) auf der Kompositionsbeziehung unterstützt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-30df05c99bb4cd43", "to": "FIG-2d2f806c5b31cc99", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Assoziation <code>«isOfType»</code> von <code>SwComponentPrototype</code> zu <code>SwComponentType</code>: Die explizite Kardinalitätsangabe <code>*</code> am Quellende (<code>SwComponentPrototype</code>) wurde entfernt (Default-Multiplizität in UML für offene Assoziationsenden).\n</li></ul>"}]};
